def gen(rng):
    def fmt(k, a):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))
    tests = [fmt(0, [5]), fmt(1, [5]), fmt(0, [3, 1, 2]), fmt(3, [3, 1, 2]), fmt(2, [4, 4, 4, 4]),
             fmt(1, [-5, 9, 0, -5, 9]), fmt(4, [-10**9, 10**9, 0, -10**9, 10**9])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(2):
            k = rng.randint(0, n)
            hi = rng.choice([3, 20, 1000])
            tests.append(fmt(k, [rng.randint(-hi, hi) for _ in range(n)]))
    N = 150000
    tests.append(fmt(N // 3, [rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(0, [rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(N, list(range(N, 0, -1))))
    tests.append(fmt(N // 2, [rng.randint(1, 5) for _ in range(N)]))
    return tests

